// Store a stable person identifier in the existing, backed-up catalogue.
const PERSON_OVERRIDE_PREFIX='@person-override:';
function personOverride(name){return personalCatalog.find(x=>x.field==='history'&&x.name.startsWith(PERSON_OVERRIDE_PREFIX)&&x.time_label===name)}
function personLabelOverride(name){const item=personOverride(name);return item?.verse||''}
function personVisible(name){return !personOverride(name)?.hidden}
function traitLabel(name){return subjectOverride('traits',name)?.display_name||name}
async function personOverrideKey(name){const existing=personOverride(name);if(existing)return existing.name;if(globalThis.crypto?.subtle){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(name));return PERSON_OVERRIDE_PREFIX+Array.from(new Uint8Array(bytes),x=>x.toString(16).padStart(2,'0')).join('').slice(0,56)}return PERSON_OVERRIDE_PREFIX+(crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2))}
function addSubjectDelete(dialog,onDelete){const form=dialog.querySelector('form'),button=document.createElement('button');button.type='button';button.className='personal-subject-delete';button.textContent='이 항목 삭제';button.onclick=async()=>{button.disabled=true;try{if(await onDelete())dialog.close()}finally{button.disabled=false}};form.append(button)}
async function setPersonOverride(name,label,hidden){const marker=await personOverrideKey(name),data={field:'history',name:marker,time_label:name,verse:label};const result=await personalWithPin(pin=>rpc('study_subject_catalog_change',{p_password:pin,p_action:'save',p_data:data}));if(!result)return false;if(hidden){const removed=await personalWithPin(pin=>rpc('study_subject_catalog_change',{p_password:pin,p_action:'hide',p_data:{field:'history',name:marker}}));if(!removed)return false}personalCatalog=await getAll('study_subject_catalog');return true}
function openPersonSubjectEditor(name){const d=document.createElement('dialog');d.className='personal-edit-dialog personal-add-sheet';d.innerHTML='<form class="personal-edit-form"><div class="personal-edit-head"><h2>인물 수정</h2><button type="button" data-close aria-label="닫기">×</button></div><label>인물 이름<input name="name" maxlength="100" required autocomplete="off"></label><p class="personal-edit-error" role="status"></p><button type="submit" class="primary">저장</button></form>';document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();d.addEventListener('close',()=>d.remove(),{once:true});const f=d.querySelector('form');f.elements.name.value=displayName(name);addSubjectDelete(d,async()=>{if(!confirm('목록에서 이 인물을 지울까요?'))return false;try{if(!await setPersonOverride(name,displayName(name),true))return false;location.hash='#/people';return true}catch(err){showPersonalError(d.querySelector('.personal-edit-error'),err);return false}});f.onsubmit=async e=>{e.preventDefault();const label=f.elements.name.value.trim(),err=d.querySelector('.personal-edit-error'),btn=f.querySelector('[type=submit]');if(!label)return;if(allPeople().some(p=>p.name!==name&&displayName(p.name)===label)){err.textContent='이미 같은 이름의 인물이 있어요. 구분할 수 있는 이름을 입력해 주세요.';return}btn.disabled=true;btn.setAttribute('aria-busy','true');try{if(!await setPersonOverride(name,label,false))return;d.close();personView(name)}catch(error){showPersonalError(err,error)}finally{btn.disabled=false;btn.removeAttribute('aria-busy')}};d.showModal()}
